VERIFIED = 'verified'
MISSING = 'missing'
UNREACHABLE = 'unreachable'
WELL_KNOWN = '/.well-known/genlayer-attest.txt'
GIST_HOST = 'api.github.com'
_MAX_DOMAIN = 100
_MAX_HANDLE = 39
_MAX_GIST = 64

def valid_domain(domain: str) -> bool:
    d = (domain or '').strip().lower()
    if not d or len(d) > _MAX_DOMAIN or d.startswith('.') or d.endswith('.') or ('..' in d):
        return False
    if d.startswith('-') or d.endswith('-'):
        return False
    for ch in d:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or ch in '-.'):
            return False
    return '.' in d

def valid_handle(handle: str) -> bool:
    h = (handle or '').strip()
    if not h or len(h) > _MAX_HANDLE:
        return False
    if h.startswith('-') or h.endswith('-') or '--' in h:
        return False
    for ch in h:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or 'A' <= ch <= 'Z' or (ch == '-')):
            return False
    return True

def valid_gist_id(gist_id: str) -> bool:
    g = (gist_id or '').strip()
    if not g or len(g) > _MAX_GIST:
        return False
    for ch in g:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'f' or 'A' <= ch <= 'F'):
            return False
    return True

def token_for(owner_hex: str, kind: str, resource: str) -> str:
    return 'genlayer-attest=' + owner_hex.strip().lower() + ':' + kind + ':' + resource.strip().lower()

def domain_url(domain: str) -> str:
    return 'https://' + domain.strip().lower() + WELL_KNOWN

def gist_url(gist_id: str) -> str:
    return 'https://' + GIST_HOST + '/gists/' + gist_id.strip()

def token_present(body: str, token: str) -> bool:
    if not token:
        return False
    for line in (body or '').replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        if line.strip() == token:
            return True
    return False

def gist_owner(document) -> str:
    if not isinstance(document, dict):
        return ''
    owner = document.get('owner')
    if not isinstance(owner, dict):
        return ''
    login = owner.get('login')
    return login if isinstance(login, str) else ''

def gist_text(document) -> str:
    if not isinstance(document, dict):
        return ''
    files = document.get('files')
    if not isinstance(files, dict):
        return ''
    parts = []
    for name in sorted(files):
        entry = files[name]
        if not isinstance(entry, dict) or entry.get('truncated') is True:
            continue
        content = entry.get('content')
        if isinstance(content, str):
            parts.append(content)
    return '\n'.join(parts)

def same_handle(a: str, b: str) -> bool:
    return (a or '').strip().lower() == (b or '').strip().lower()

def epoch_seconds(stamp: str):
    s = (stamp or '').strip()
    if len(s) < 19 or s[4] != '-' or s[7] != '-' or (s[10] != 'T') or (s[13] != ':') or (s[16] != ':'):
        return None
    for i in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15, 17, 18):
        if not '0' <= s[i] <= '9':
            return None
    year, month, day = (int(s[0:4]), int(s[5:7]), int(s[8:10]))
    hour, minute, second = (int(s[11:13]), int(s[14:16]), int(s[17:19]))
    if not 1 <= month <= 12 or day < 1 or day > _days_in_month(year, month):
        return None
    if hour > 23 or minute > 59 or second > 60:
        return None
    return _days_from_civil(year, month, day) * 86400 + hour * 3600 + minute * 60 + second

def _days_in_month(year: int, month: int) -> int:
    if month == 2:
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        return 29 if leap else 28
    return 30 if month in (4, 6, 9, 11) else 31

def _days_from_civil(year: int, month: int, day: int) -> int:
    y = year - (1 if month <= 2 else 0)
    era = (y if y >= 0 else y - 399) // 400
    year_of_era = y - era * 400
    day_of_year = (153 * (month + (-3 if month > 2 else 9)) + 2) // 5 + day - 1
    day_of_era = year_of_era * 365 + year_of_era // 4 - year_of_era // 100 + day_of_year
    return era * 146097 + day_of_era - 719468

def end_of_day(day: str):
    stamp = (day or '').strip()
    if len(stamp) != 10:
        return None
    return epoch_seconds(stamp + 'T23:59:59Z')

def next_day(day: str):
    at = epoch_seconds((day or '').strip() + 'T12:00:00Z')
    if at is None:
        return None
    return _civil_from_days(at // 86400 + 1)

def _civil_from_days(days: int) -> str:
    z = days + 719468
    era = (z if z >= 0 else z - 146096) // 146097
    day_of_era = z - era * 146097
    year_of_era = (day_of_era - day_of_era // 1460 + day_of_era // 36524 - day_of_era // 146096) // 365
    year = year_of_era + era * 400
    day_of_year = day_of_era - (365 * year_of_era + year_of_era // 4 - year_of_era // 100)
    mp = (5 * day_of_year + 2) // 153
    day = day_of_year - (153 * mp + 2) // 5 + 1
    month = mp + (3 if mp < 10 else -9)
    if month <= 2:
        year += 1
    return f'{year:04d}-{month:02d}-{day:02d}'
from dataclasses import dataclass
import genlayer as gl
from genlayer.types import *
FRESH_SECONDS = 30 * 24 * 3600

@gl.storage.allow
@dataclass
class Binding:
    owner: Address
    kind: str
    resource: str
    claim_id: str
    proof: Address
    verified_at: str
    adopted_at: str
    live: bool
    withdrawn_at: str

class Link(gl.contract.Contract):
    bindings: gl.storage.TreeMap[str, Binding]
    binding_ids: gl.storage.DynArray[str]

    def __init__(self):
        pass

    @gl.public.write
    def adopt(self, proof: str, claim_id: str) -> dict:
        at = _address(proof)
        key = claim_id.strip().lower()
        record = gl.contract.get_at(at).view().get_claim(key)
        if str(record['status']) != VERIFIED:
            raise gl.vm.UserError('that claim is not verified: ' + str(record['status'] or 'never checked'))
        owner = _address(record['owner'])
        if owner.as_hex.lower() != gl.message.sender_address.as_hex.lower():
            raise gl.vm.UserError('only the address that proved it may publish it')
        binding_id = at.as_hex.lower() + '|' + key
        if binding_id in self.bindings and self.bindings[binding_id].live:
            raise gl.vm.UserError('that binding is already published')
        fresh = Binding(owner=owner, kind=str(record['kind']), resource=str(record['resource']), claim_id=key, proof=at, verified_at=str(record['checked_at']), adopted_at=_stamp(), live=True, withdrawn_at='')
        first_time = binding_id not in self.bindings
        self.bindings[binding_id] = fresh
        if first_time:
            self.binding_ids.append(binding_id)
        return _as_dict(binding_id, fresh, _now())

    @gl.public.write
    def refresh(self, binding_id: str) -> dict:
        key = binding_id.strip().lower()
        if key not in self.bindings:
            raise gl.vm.UserError('no such binding: ' + key)
        binding = self.bindings[key]
        record = gl.contract.get_at(binding.proof).view().get_claim(binding.claim_id)
        status = str(record['status'])
        if status == VERIFIED:
            binding.verified_at = str(record['checked_at'])
            binding.live = True
            binding.withdrawn_at = ''
        elif status == MISSING:
            binding.live = False
            binding.withdrawn_at = _stamp()
        self.bindings[key] = binding
        return _as_dict(key, binding, _now())

    @gl.public.write
    def withdraw(self, binding_id: str) -> dict:
        key = binding_id.strip().lower()
        if key not in self.bindings:
            raise gl.vm.UserError('no such binding: ' + key)
        binding = self.bindings[key]
        if binding.owner.as_hex.lower() != gl.message.sender_address.as_hex.lower():
            raise gl.vm.UserError('only the owner may withdraw a binding')
        if not binding.live:
            raise gl.vm.UserError('that binding is already down')
        binding.live = False
        binding.withdrawn_at = _stamp()
        self.bindings[key] = binding
        return _as_dict(key, binding, _now())

    @gl.public.view
    def resolve(self, kind: str, resource: str) -> dict:
        want_kind = kind.strip().lower()
        want_resource = resource.strip().lower()
        now = _now()
        found = []
        for binding_id in self.binding_ids:
            binding = self.bindings[binding_id]
            if binding.live and binding.kind == want_kind and (binding.resource == want_resource):
                found.append(_as_dict(binding_id, binding, now))
        return {'kind': kind.strip().lower(), 'resource': resource.strip().lower(), 'bindings': found, 'contested': len(found) > 1, 'fresh': [b for b in found if b['fresh']]}

    @gl.public.view
    def controls(self, kind: str, resource: str, address: str) -> bool:
        who = _address(address).as_hex.lower()
        for binding in self.resolve(kind, resource)['fresh']:
            if str(binding['owner']).lower() == who:
                return True
        return False

    @gl.public.view
    def holdings(self, address: str) -> list:
        who = _address(address).as_hex.lower()
        now = _now()
        return [_as_dict(b, self.bindings[b], now) for b in self.binding_ids if self.bindings[b].owner.as_hex.lower() == who]

    @gl.public.view
    def get_binding(self, binding_id: str) -> dict:
        key = binding_id.strip().lower()
        if key not in self.bindings:
            raise gl.vm.UserError('no such binding: ' + key)
        return _as_dict(key, self.bindings[key], _now())

    @gl.public.view
    def binding_list(self) -> list:
        return [b for b in self.binding_ids]

    @gl.public.view
    def count(self) -> int:
        return len(self.binding_ids)

def _stamp() -> str:
    return str(gl.message.raw['datetime'])

def _now():
    return epoch_seconds(_stamp())

def _address(value) -> Address:
    if hasattr(value, 'as_hex'):
        return value
    return Address(str(value).strip())

def _as_dict(key: str, binding: Binding, now) -> dict:
    seen = epoch_seconds(binding.verified_at)
    age = -1
    fresh = False
    if seen is not None and now is not None and (now >= seen):
        age = now - seen
        fresh = binding.live and age <= FRESH_SECONDS
    return {'binding_id': key, 'owner': binding.owner.as_hex, 'kind': binding.kind, 'resource': binding.resource, 'claim_id': binding.claim_id, 'proof': binding.proof.as_hex, 'verified_at': binding.verified_at, 'adopted_at': binding.adopted_at, 'live': binding.live, 'withdrawn_at': binding.withdrawn_at, 'age_seconds': str(age), 'fresh': fresh, 'fresh_for_seconds': str(FRESH_SECONDS)}
